def match_parens(lst):
    open_count1, close_count1 = lst[0].count('('), lst[0].count(')')
    open_count2, close_count2 = lst[1].count('('), lst[1].count(')')

    total_open = open_count1 + open_count2
    total_close = close_count1 + close_count2

    if total_open != total_close:
        return 'No'

    current_open = 0
    # Try to combine lst[0] then lst[1]
    for char in lst[0] + lst[1]:
        if char == '(':
            current_open += 1
        else:  # char == ')'
            current_open -= 1
        if current_open < 0:
            break
    else:
        if current_open == 0:
            return 'Yes'

    # Try to combine lst[1] then lst[0]
    current_open = 0
    for char in lst[1] + lst[0]:
        if char == '(':
            current_open += 1
        else:  # char == ')'
            current_open -= 1
        if current_open < 0:
            return 'No'

    return 'Yes' if current_open == 0 else 'No'
