def match_parens(lst):
    open_count_1, close_count_1 = lst[0].count('('), lst[0].count(')')
    open_count_2, close_count_2 = lst[1].count('('), lst[1].count(')')

    # Total open and close parenthesis
    total_open = open_count_1 + open_count_2
    total_close = close_count_1 + close_count_2

    # To form a balanced string, total opens must equal total closes
    if total_open != total_close:
        return 'No'

    # Check the balance of concatenations in both orders
    def is_balanced(s):
        count = 0
        for char in s:
            if char == '(':
                count += 1
            else:
                count -= 1
            if count < 0:
                return False
        return count == 0

    if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]):
        return 'Yes'
    else:
        return 'No'
